// Псевдо-C, восстановленный декомпилятором (упрощённо)
void unlock(char *s) {
    // декомпилятор свёл сравнение к массиву байтов
    char key[8];
    key[0] = 0x6b;  // 'k'
    key[1] = 0x33;  // '3'
    key[2] = 0x79;  // 'y'
    key[3] = 0x21;  // '!'
    key[4] = 0x7a;  // 'z'
    key[5] = 0x30;  // '0'
    key[6] = 0x72;  // 'r'
    key[7] = 0x00;
    if (strcmp(s, key) == 0) {
        grant_access();
    }
}
